DO $$ DECLARE s text; BEGIN
s:=pg_get_viewdef('public.dispatch_operational_jobs'::regclass,true); s:=replace(s,'NULL::timestamp with time zone AS scheduled_for','d.scheduled_for'); EXECUTE 'CREATE OR REPLACE VIEW public.dispatch_operational_jobs AS '||s;
s:=pg_get_functiondef('public.admin_bulk_assign(jsonb,text,boolean)'::regprocedure);
s:=replace(s,'response jsonb;','response jsonb; prior_item jsonb; prior_job jsonb; reserved integer;');
s:=replace(s,'IF NOT _preview THEN response:=', 'IF _preview THEN reserved:=0; FOR prior_item IN SELECT value FROM jsonb_array_elements(_jobs) WHERE value->>''assignee''=item->>''assignee'' AND value->>''id''<>item->>''id'' AND EXISTS(SELECT 1 FROM jsonb_array_elements(results) r WHERE r->>''id''=value->>''id'' AND (r->>''ok'')::boolean) LOOP reserved:=reserved+1; EXECUTE format(''SELECT to_jsonb(t) FROM public.%I t WHERE id=$1'',CASE WHEN prior_item->>''kind''=''booking'' THEN ''bookings'' ELSE ''deliveries'' END) INTO prior_job USING (prior_item->>''id'')::uuid; IF (j->>''scheduled_for'' IS NOT NULL OR prior_job->>''scheduled_for'' IS NOT NULL) AND (j->>''scheduled_for'' IS NULL OR prior_job->>''scheduled_for'' IS NULL OR (coalesce((j->>''scheduled_until'')::timestamptz,''infinity''::timestamptz)>(prior_job->>''scheduled_for'')::timestamptz AND coalesce((prior_job->>''scheduled_until'')::timestamptz,''infinity''::timestamptz)>(j->>''scheduled_for'')::timestamptz)) THEN RAISE EXCEPTION ''Selected batch has overlapping or unknown commitment windows with job %'',prior_item->>''id''; END IF; END LOOP; IF (check_result->>''load'')::integer+reserved>=3 THEN RAISE EXCEPTION ''Selected batch exceeds capacity including pending offers''; END IF; END IF; IF NOT _preview THEN response:=');
EXECUTE s;
END $$;